export default function ({ brands, records, offset, previous, keyword }) {
  if (!Array.isArray(brands) || !brands[0]?.fields || !Array.isArray(records))
    throw Error("Missing brand or keyword records");
  const rows = [...(previous?.rows ?? []), ...records],
    state = { rows, offset: offset || null };
  if (offset)
    return {
      state,
      nextOffset: offset,
      more: true,
      found: false,
      contentId: "no-content",
      brand: brands[0].fields,
    };
  for (const r of rows) {
    const f = r.fields || {};
    if (
      String(f.Keyword || "")
        .toLowerCase()
        .includes(keyword.toLowerCase()) &&
      Array.isArray(f.RelatedContent) &&
      f.RelatedContent.length
    ) {
      return {
        state,
        nextOffset: null,
        more: false,
        found: true,
        contentId: String(f.RelatedContent[0]),
        brand: brands[0].fields,
      };
    }
  }
  return {
    state,
    nextOffset: null,
    more: false,
    found: false,
    contentId: "no-content",
    brand: brands[0].fields,
  };
}

