export default function ({ result, previous }) {
  if (
    !result ||
    !Array.isArray(result.scenes) ||
    result.scenes.length !== 4 ||
    !result.thumbnail_prompt
  )
    throw Error("Expected four scenes and a thumbnail");
  const tasks = [
    { name: "Thumbnail", prompt: result.thumbnail_prompt },
    ...result.scenes.map((s, i) => ({
      name: `Scene ${i + 1}`,
      prompt: s.image_prompt,
      script: s.script,
    })),
  ];
  if (
    tasks.some((t) => typeof t.prompt !== "string" || !t.prompt.trim() || t.prompt.length > 2000) ||
    result.scenes.some((s) => !s.script)
  )
    throw Error("Invalid scene prompt");
  const i = (previous?.i ?? -1) + 1,
    t = tasks[i] || {};
  return {
    state: { i },
    more: i < tasks.length,
    slot: t.name || "",
    prompt: t.prompt || "",
    script: t.script || "",
  };
}

