export default async function ({ contentId, slot, prompt }, ctx) {
  const key = `brand-image:${contentId}:${slot}`,
    s = await ctx.state.get(key);
  if (s?.status === "submitting" || s?.status === "saving")
    throw Error("Inspect Leonardo or Airtable before clearing pending state");
  if (s?.status === "done") return { key, skip: true, submitted: true, generationId: "", body: {} };
  if (s?.status === "submitted")
    return { key, skip: false, submitted: true, generationId: s.generationId, body: {} };
  await ctx.state.set(key, { status: "submitting" });
  return {
    key,
    skip: false,
    submitted: false,
    generationId: "",
    body: {
      modelId: "de7d3faf-762f-48e0-b3b7-9d0ac3a3fcf3",
      prompt,
      width: 720,
      height: 1280,
      num_images: 1,
      contrast: 3.5,
      alchemy: false,
      ultra: false,
      public: false,
    },
  };
}

