export default async function ({ key, body }, ctx) {
  const id = body?.sdGenerationJob?.generationId;
  if (typeof id !== "string" || !id) throw Error("Unknown Leonardo submission outcome");
  await ctx.state.set(key, { status: "submitted", generationId: id });
  return { generationId: id };
}

