export default async function ({ key, previous }, ctx) {
  const s = await ctx.state.get(key);
  if (s?.status !== "submitted" || !s.generationId) throw Error("Missing generation ID");
  const attempts = previous?.key === key ? previous.attempts + 1 : 1;
  if (attempts > 20) throw Error("Generation still pending; retry later");
  return {
    state: { key, attempts },
    url: "https://cloud.leonardo.ai/api/rest/v1/generations/" + encodeURIComponent(s.generationId),
  };
}

