export default function ({ body }) {
  const g = body?.generations_by_pk;
  if (!g || !["PENDING", "COMPLETE", "FAILED"].includes(g.status))
    throw Error("Invalid generation status");
  if (g.status === "FAILED") throw Error("Leonardo generation failed");
  if (g.status === "PENDING") return { ready: false, url: "" };
  const url = g.generated_images?.[0]?.url;
  if (typeof url !== "string" || !url.startsWith("https://"))
    throw Error("Completed generation has no image");
  return { ready: true, url };
}

