export default async function ({ key, url, title, slot, script }, ctx) {
  const s = await ctx.state.get(key);
  if (s?.status !== "submitted") throw Error("Generation not confirmed");
  await ctx.state.set(key, { ...s, status: "saving" });
  return {
    records: [
      {
        fields: {
          "Asset URL": url,
          "Asset Name": `${slot} - ${title}${script ? " - " + script : ""}`,
          "Asset Type": "Image",
        },
      },
    ],
  };
}

